import { pgTable, serial, text, timestamp } from "drizzle-orm/pg-core";

// Better Auth tables (user/session/account/verification), generated by `npx auth@latest generate`.
// Regenerate that file rather than hand-editing it when auth plugins change.
export * from "./auth-schema.js";

// First table: proves migrations apply to a fresh Neon branch and gives /health a row to read.
export const appMeta = pgTable("app_meta", {
  id: serial("id").primaryKey(),
  key: text("key").notNull().unique(),
  value: text("value").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});
